// Synthetic 32x32 flat-color HEIC, generated with local macOS ImageIO on
// 2026-09-09. No camera image/customer data; original encoder input was a
// 4096-byte RGBA buffer filled with 128. Stored inline to avoid OS-specific
// encoders in CI and to test HEVC decoding independently of Sharp encoding.
export function syntheticHeic(): Buffer {
  return Buffer.from(
    "",
    "base64",
  );
}
